'use strict';
const $=id=>document.getElementById(id);
const categoryNames={characters:'キャラクター',zones:'エリア',monsters:'モンスター',items:'アイテム・装備',skills:'スキル',nodes:'マップ地点',rarities:'レアリティ',materials:'素材',shops:'ショップ'};
const fieldNames={id:'固定ID',name:'名前',job:'ジョブ',characterId:'使用者',target:'対象',speed:'素早さ',hp:'HP',atk:'攻撃力',def:'守備力',wis:'賢さ',xp:'経験値',gold:'所持金・報酬',price:'価格',value:'補正値',cost:'消費MP',lv:'習得レベル',zoneId:'エリア',nodeId:'街の地点',itemIds:'販売商品',equipmentDropIds:'装備ドロップ候補',drops:'ドロップ素材',links:'接続先（双方向）',rarity:'レアリティ',level:'装備レベル',bonusEffects:'装備の追加効果',stat:'能力値',amount:'加算値',bossId:'ボス',category:'分類',effects:'効果',actions:'行動（JSON：能力低下を付ける確率行動）',desc:'説明',type:'種類',power:'倍率',base:'基礎値',shape:'姿',rate:'確率',x:'地図X',y:'地図Y',town:'街',boss:'ボス',common:'基本素材',bonusItemId:'装備ドロップ（旧形式）',travelMaterials:'道中の素材',party:'初期隊列',baseLuck:'うんのよさ（初期値）',luckPerLevel:'うんのよさ（レベル上昇分）',stats:'個別成長（省略時は既定値）',growth:'成長',travel:'道中',battle:'戦闘',inn:'宿屋',normalAttack:'通常攻撃',multiplier:'上昇倍率',turns:'継続ターン',unique:'固有装備（ドロップ時に抽選しない）',gearRoll:'ドロップ装備の抽選',rarityRates:'レアリティの確率（合計1）',statRates:'追加効果の係数（装備Lv1あたり）',rarityRanges:'追加効果の倍率の幅［最小, 最大］'};
let working=null,version=null,category='monsters',index=0,dirty=false;
function status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'content-type':'application/json'}}),result=await response.json();if(!response.ok)throw new Error(result.error||'接続できません');return result;}
const draft=()=>version?.status==='draft';
function changed(){dirty=true;$('versionInfo').textContent='未保存の変更があります。保存後にプレビュー・公開してください。';$('preview').disabled=true;$('publish').disabled=true;}
function reference(key){return {characterId:'characters',zoneId:'zones',nodeId:'nodes',bossId:'monsters',rarity:'rarities',common:'materials',bonusItemId:'items',equipmentDropIds:'items',links:'nodes',drops:'materials',itemIds:'items',travelMaterials:'materials',party:'characters'}[key];}
function drawList(){const filter=$('search').value.toLowerCase();$('entries').replaceChildren();working[category].forEach((entry,i)=>{if(filter&&!((entry.name||'')+' '+entry.id).toLowerCase().includes(filter))return;const button=document.createElement('button');button.type='button';button.setAttribute('aria-pressed',String(i===index));button.textContent=entry.name||entry.id;const small=document.createElement('small');small.textContent=entry.id;button.append(small);button.onclick=()=>{index=i;drawList();drawEditor();};$('entries').append(button);});}
function field(key,value,parent,onchange,entry=null){const label=document.createElement('label');label.textContent=fieldNames[key]||key;let control;const gearRarity=key==='rarity'&&category==='items'&&entry?.category==='gear',references=gearRarity?null:reference(key);
 if(gearRarity){control=document.createElement('select');for(const [id,name]of [['common','コモン'],['uncommon','アンコモン'],['rare','レア'],['epic','エピック'],['legendary','レジェンダリー']]){const option=document.createElement('option');option.value=id;option.textContent=name;control.append(option);}control.value=value;control.onchange=()=>{onchange(control.value);changed();};}
 else if(references){control=document.createElement('select');control.multiple=Array.isArray(value);const rows=key==='equipmentDropIds'?working.items.filter(item=>item.category==='gear'):working[references];if(control.multiple)control.size=Math.min(6,Math.max(3,rows.length));for(const row of rows){const option=document.createElement('option');option.value=row.id;option.textContent=(row.name||row.id)+' ('+row.id+')';option.selected=Array.isArray(value)?value.includes(row.id):value===row.id;control.append(option);}control.onchange=()=>{onchange(control.multiple?Array.from(control.selectedOptions,o=>o.value):control.value);changed();};}
 else if(key==='target'){control=document.createElement('select');for(const [optionValue,text]of [['ally','味方'],['self','自分'],['allEnemies','敵全体']]){const option=document.createElement('option');option.value=optionValue;option.textContent=text;control.append(option);}control.value=value;control.onchange=()=>{onchange(control.value);changed();};}
 else if(typeof value==='boolean'){control=document.createElement('input');control.type='checkbox';control.checked=value;control.onchange=()=>{onchange(control.checked);changed();};}
 else if(typeof value==='number'||typeof value==='string'||value===null){control=document.createElement('input');control.type=typeof value==='number'||value===null?'number':'text';if(typeof value==='number')control.step='any';control.value=value??'';control.onchange=()=>{onchange(typeof value==='number'||value===null?(control.value===''?null:Number(control.value)):control.value);changed();if(key==='id'||key==='name')drawList();};}
 else{control=document.createElement('textarea');control.value=JSON.stringify(value,null,2);control.onchange=()=>{try{onchange(JSON.parse(control.value));control.setCustomValidity('');changed();}catch{control.setCustomValidity('正しいJSONを入力してください');control.reportValidity();}};label.className='wide';}
 control.disabled=!draft();control.dataset.field=key;label.append(control);parent.append(label);}
function drawEffects(entry,form){const container=document.createElement('section');container.className='wide';const heading=document.createElement('h3');heading.textContent='効果';container.append(heading);entry.effects.forEach((effect,i)=>{const row=document.createElement('div');row.className='effect';const select=document.createElement('select');select.setAttribute('aria-label','効果の種類');for(const type of GameContent.effectTypes){const option=document.createElement('option');option.value=type;option.textContent=type;select.append(option);}select.value=effect.type;select.disabled=!draft();select.onchange=()=>{const type=select.value;for(const key of ['power','base','amount','full','multiplier','turns'])delete effect[key];Object.assign(effect,type==='attackBuff'?{type,multiplier:1.5,turns:3}:GameContent.debuffEffectTypes.includes(type)?{type,multiplier:0.7,turns:3}:['restoreHP','restoreMP'].includes(type)?{type,amount:45}:{type,power:1,base:0});changed();drawEditor();};row.append(select);for(const key of ['power','base','amount','full','multiplier','turns'])if(key in effect)field(key,effect[key],row,value=>effect[key]=value);const remove=document.createElement('button');remove.type='button';remove.textContent='この効果を削除';remove.disabled=!draft();remove.onclick=()=>{entry.effects.splice(i,1);changed();drawEditor();};row.append(remove);container.append(row);});const add=document.createElement('button');add.type='button';add.textContent='効果を追加';add.disabled=!draft();add.onclick=()=>{entry.effects.push({type:'magicDamage',power:1,base:0});changed();drawEditor();};container.append(add);form.append(container);}
function drawBonusEffects(entry,form){const container=document.createElement('section');container.className='wide';const heading=document.createElement('h3');heading.textContent='固定の追加能力';container.append(heading);(entry.bonusEffects||[]).forEach((effect,i)=>{const row=document.createElement('div');row.className='effect bonus-effect';const select=document.createElement('select');select.setAttribute('aria-label','追加能力の種類');for(const stat of GameContent.bonusEffectStats){const option=document.createElement('option');option.value=stat;option.textContent=fieldNames[stat]||({maxHP:'最大HP',maxMP:'最大MP',attack:'攻撃力',defense:'守備力',wisdom:'賢さ',speed:'素早さ',luck:'うんのよさ'}[stat]);select.append(option);}select.value=effect.stat;select.disabled=!draft();select.onchange=()=>{effect.stat=select.value;changed();};row.append(select);field('amount',effect.amount,row,value=>effect.amount=value,entry);const remove=document.createElement('button');remove.type='button';remove.textContent='この追加能力を削除';remove.disabled=!draft();remove.onclick=()=>{entry.bonusEffects.splice(i,1);changed();drawEditor();};row.append(remove);container.append(row);});const add=document.createElement('button');add.type='button';add.textContent='追加能力を追加';add.disabled=!draft();add.onclick=()=>{entry.bonusEffects??=[];entry.bonusEffects.push({stat:'attack',amount:1});changed();drawEditor();};container.append(add);form.append(container);}
function drawEditor(){const entry=working[category][index];$('editor').replaceChildren();$('editorTitle').textContent=entry?.name||entry?.id||'定義がありません';if(!entry)return;for(const [key,value]of Object.entries(category==='characters'?{stats:{},...entry}:category==='items'&&entry.category==='gear'?{unique:false,...entry}:entry)){if(key==='effects')drawEffects(entry,$('editor'));else if(key==='bonusEffects')drawBonusEffects(entry,$('editor'));else field(key,value,$('editor'),next=>entry[key]=next,entry);}}
function drawRules(){$('rulesEditor').replaceChildren();for(const [section,values]of Object.entries(working.rules)){if(section==='gearRoll'){drawGearRoll(values);continue;}if(Array.isArray(values)){field(section,values,$('rulesEditor'),value=>working.rules[section]=value);continue;}const group=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=fieldNames[section]||section;group.append(legend);for(const [key,value]of Object.entries(values))field(key,value,group,next=>values[key]=next);$('rulesEditor').append(group);}}
function draw(){drawRules();for(const id of ['save','add','duplicate','remove','label'])$(id).disabled=!draft();$('label').value=version.label;$('preview').disabled=dirty;$('publish').disabled=dirty;$('versionInfo').textContent=version.status==='draft'?'下書き · 更新番号 '+version.revision:'公開済みの定義は変更できません。下書きへ複製してください。';drawList();drawEditor();}
async function load(id){if(dirty&&!confirm('未保存の変更を破棄して読み込みますか？')){$('versions').value=version.id;return;}version=await api('/api/admin/versions/'+encodeURIComponent(id));working=GameContent.withJobs(version.data,GameData);dirty=false;index=0;draw();status('定義を読み込みました。');}
async function versions(selected){const result=await api('/api/admin/versions');$('versions').replaceChildren();for(const row of result.versions){const option=document.createElement('option');option.value=row.id;option.textContent=(row.id===result.activeId?'【現在の公開版】':row.status==='draft'?'【下書き】':'【公開済み】')+row.label;$('versions').append(option);}$('versions').value=selected||result.activeId;await load($('versions').value);}
function run(fn){return async()=>{try{await fn();}catch(error){status(error.message,true);}};}
$('versions').onchange=run(()=>load($('versions').value));$('category').onchange=()=>{category=$('category').value;index=0;drawList();drawEditor();};$('search').oninput=drawList;$('label').onchange=()=>{version.label=$('label').value;changed();};$('editor').onsubmit=event=>event.preventDefault();
$('create').onclick=run(async()=>{if(dirty&&!confirm('未保存の変更を破棄して新しい下書きを作りますか？'))return;const result=await api('/api/admin/drafts',{method:'POST',body:JSON.stringify({sourceId:version.id,label:version.label+' のコピー'})});dirty=false;await versions(result.id);status('下書きを作成しました。');});
$('save').onclick=run(async()=>{if(!draft())return;const errors=GameContent.validate(working);if(errors.length)throw new Error(errors.join('\n'));const result=await api('/api/admin/versions/'+version.id,{method:'PUT',body:JSON.stringify({data:working,label:$('label').value,revision:version.revision})});version.revision=result.revision;dirty=false;draw();status('下書きを保存しました。');});
$('validate').onclick=()=>{const errors=GameContent.validate(working);status(errors.length?errors.join('\n'):'検証に合格しました。ID・参照・マップ接続・効果を確認しました。',!!errors.length);};
$('preview').onclick=()=>{if(dirty)return;window.open('/?preview='+encodeURIComponent(version.id),'_blank','noopener');};
$('publish').onclick=run(async()=>{if(dirty||!confirm('この定義をゲームへ公開しますか？ 次回の読み込みから反映します。以前の公開版へ戻すこともできます。'))return;await api('/api/admin/versions/'+version.id+'/publish',{method:'POST',body:JSON.stringify({revision:version.revision})});await versions(version.id);status('公開版を切り替えました。ゲームを再読み込みすると反映されます。');});
$('export').onclick=()=>{const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(working,null,2)],{type:'application/json'}));link.download='game-content-'+version.id+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);};
$('import').onchange=run(async()=>{const file=$('import').files[0];if(!file)return;if(file.size>2_000_000)throw new Error('ファイルが大きすぎます');const data=JSON.parse(await file.text()),errors=GameContent.validate(data);if(errors.length)throw new Error(errors.join('\n'));if(dirty&&!confirm('未保存の変更を破棄しますか？'))return;const result=await api('/api/admin/drafts',{method:'POST',body:JSON.stringify({data,label:file.name})});dirty=false;await versions(result.id);status('下書きとして取り込みました。公開前にプレビューしてください。');});
function add(copy){if(!draft())return;const sample=copy?working[category][index]:working[category][0];if(!sample)return;const entry=structuredClone(sample);let id=entry.id+'_copy';while(working[category].some(e=>e.id===id))id+='_1';entry.id=id;if(entry.name)entry.name+='（新規）';working[category].push(entry);index=working[category].length-1;changed();drawList();drawEditor();}
$('add').onclick=()=>add(false);$('duplicate').onclick=()=>add(true);
$('remove').onclick=()=>{if(!draft())return;const entry=working[category][index];if(!entry||!confirm((entry.name||entry.id)+'を削除しますか？'))return;const next=structuredClone(working);next[category].splice(index,1);const errors=GameContent.validate(next);if(errors.length){status('削除できません。参照先や必須の定義を確認してください。\n'+errors.join('\n'),true);return;}working=next;index=0;changed();drawList();drawEditor();};
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
for(const [key,name]of Object.entries(categoryNames)){const option=document.createElement('option');option.value=key;option.textContent=name;$('category').append(option);}$('category').value=category;
versions().catch(error=>status(error.message,true));
// ドロップ装備の抽選ルール（rules.gearRoll）の専用フォーム。確率は％で入力し、数値の範囲を装備Lvごとにプレビューする。
const gearRarityNames={common:'コモン',uncommon:'アンコモン',rare:'レア',epic:'エピック',legendary:'レジェンダリー'},gearRolledRarities=['uncommon','rare','epic','legendary'],gearStatNames={maxHP:'最大HP',maxMP:'最大MP',attack:'攻撃力',defense:'守備力',wisdom:'賢さ',speed:'素早さ',luck:'うんのよさ'};
let gearPreviewLevel=10;
function numberInput(label,value,onchange,attrs={}){const wrap=document.createElement('label');wrap.textContent=label;const input=document.createElement('input');input.type='number';input.step='any';Object.assign(input,attrs);input.value=value??'';input.disabled=!draft();input.onchange=()=>{if(input.value==='')return;onchange(Number(input.value));changed();drawGearRollPreview();};wrap.append(input);return wrap;}
function drawGearRoll(roll){const group=document.createElement('fieldset');group.className='gear-roll';group.id='gearRollEditor';const legend=document.createElement('legend');legend.textContent=fieldNames.gearRoll;group.append(legend);
 const note=document.createElement('p');note.className='hint';note.textContent='固有装備以外のドロップ装備に使います。数値は max(1, 四捨五入(係数 × 装備Lv × 倍率)) です。';group.append(note);
 const rates=document.createElement('div');rates.className='gear-roll-grid';const ratesTitle=document.createElement('h3');ratesTitle.textContent='レアリティの確率（％・合計100）';group.append(ratesTitle);
 for(const id of Object.keys(gearRarityNames))rates.append(numberInput(gearRarityNames[id],Math.round(roll.rarityRates[id]*1e6)/1e4,value=>roll.rarityRates[id]=Math.round(value*1e4)/1e6,{min:0,max:100,step:0.1,name:'rate-'+id}));
 const total=document.createElement('p');total.id='gearRateTotal';total.setAttribute('role','status');group.append(rates,total);
 const statsTitle=document.createElement('h3');statsTitle.textContent='追加効果の候補（チェックした能力）と係数（装備Lv1あたり）';group.append(statsTitle);const stats=document.createElement('div');stats.className='gear-roll-grid';
 for(const stat of GameContent.bonusEffectStats){const row=document.createElement('div');row.className='gear-roll-stat';const check=document.createElement('label');check.className='inline';const box=document.createElement('input');box.type='checkbox';box.name='stat-'+stat;box.checked=Object.hasOwn(roll.statRates,stat);box.disabled=!draft();check.append(box,document.createTextNode(gearStatNames[stat]));const rate=numberInput('係数',roll.statRates[stat],value=>roll.statRates[stat]=value,{min:0,step:0.01,name:'coef-'+stat});rate.querySelector('input').disabled=!draft()||!box.checked;box.onchange=()=>{if(box.checked)roll.statRates[stat]=Number(rate.querySelector('input').value)||0.3;else delete roll.statRates[stat];changed();drawRules();};row.append(check,rate);stats.append(row);}
 group.append(stats);const rangeTitle=document.createElement('h3');rangeTitle.textContent='追加効果の倍率の幅［最小〜最大］（最大値そのものは出ません）';group.append(rangeTitle);const ranges=document.createElement('div');ranges.className='gear-roll-grid';
 for(const id of gearRolledRarities)for(const [i,edge] of [[0,'最小'],[1,'最大']])ranges.append(numberInput(gearRarityNames[id]+'の'+edge,roll.rarityRanges[id][i],value=>roll.rarityRanges[id][i]=value,{min:0,max:10,step:0.05,name:'range-'+id+'-'+i}));
 group.append(ranges);const previewTitle=document.createElement('h3');previewTitle.textContent='追加効果の範囲のプレビュー';group.append(previewTitle);
 const level=document.createElement('label');level.textContent='装備Lv';const levelInput=document.createElement('input');levelInput.type='number';levelInput.min=1;levelInput.id='gearPreviewLevel';levelInput.value=gearPreviewLevel;levelInput.oninput=()=>{gearPreviewLevel=Math.max(1,Math.floor(Number(levelInput.value)||1));drawGearRollPreview();};level.append(levelInput);
 const table=document.createElement('div');table.id='gearRollPreview';table.className='gear-roll-preview';group.append(level,table);$('rulesEditor').append(group);drawGearRollPreview();}
function drawGearRollPreview(){const roll=working?.rules?.gearRoll,table=$('gearRollPreview'),total=$('gearRateTotal');if(!roll||!table)return;
 const sum=Object.keys(gearRarityNames).reduce((value,id)=>value+(Number(roll.rarityRates[id])||0),0);total.textContent='合計 '+Math.round(sum*1e6)/1e4+'％'+(Math.abs(sum-1)>1e-9?'（100％にしてください）':'');total.classList.toggle('error',Math.abs(sum-1)>1e-9);
 const range=(stat,id)=>{const [low,high]=roll.rarityRanges[id],rate=roll.statRates[stat],lv=gearPreviewLevel,a=Math.max(1,Math.round(rate*lv*low)),b=Math.max(1,Math.round(rate*lv*high));return a===b?'+'+a:'+'+a+'〜'+b;};
 const head='<tr><th scope="col">能力</th>'+gearRolledRarities.map(id=>'<th scope="col">'+gearRarityNames[id]+'</th>').join('')+'</tr>';
 const rows=Object.keys(roll.statRates).filter(stat=>gearStatNames[stat]).map(stat=>'<tr><th scope="row">'+gearStatNames[stat]+'</th>'+gearRolledRarities.map(id=>'<td>'+range(stat,id)+'</td>').join('')+'</tr>').join('');
 table.innerHTML='<table><caption>装備Lv'+gearPreviewLevel+'で1つの追加効果が取りうる値（上限は検証で使う値）</caption><thead>'+head+'</thead><tbody>'+rows+'</tbody></table>';}
